import { parseDate } from './src/dates.js';
import { parseEuros, formatEuros } from './src/money.js';
import { monthlyCents, nextCharge, CYCLE } from './src/cycles.js';
import { upcoming } from './src/renewals.js';

// Test case 1: Weekly plan monthly cost calculation
const plan1 = { name: 'Test', price: 1200, cycle: CYCLE.WEEK, since: '2026-10-24' };
console.log('Weekly €12.00 monthly cost:', formatEuros(monthlyCents(plan1)));

// Test case 2: Weekly plan charges every 7 days
const charges = [];
let date = '2026-10-24';
for (let i = 0; i < 5; i++) {
  charges.push(date);
  date = plan1.since; // Reset to use nextCharge
  if (i > 0) break;
}
const next = nextCharge(plan1, '2026-10-24');
console.log('First charge:', next);

const next2 = nextCharge(plan1, '2026-10-25');
console.log('First charge after today+1:', next2);

// Test case 3: Multiple charges in renewal window
const renewals = upcoming([plan1], '2026-10-24', 30);
console.log(`Found ${renewals.length} charges in 30 days:`, renewals.map(r => r.date).join(', '));

// Test case 4: Verify sorting
const multiPlan = [
  { name: 'Plan A', price: 1000, cycle: CYCLE.MONTH, since: '2026-09-02' },
  { name: 'Plan B', price: 1200, cycle: CYCLE.WEEK, since: '2026-10-24' }
];
const multiRenewals = upcoming(multiPlan, '2026-10-24', 14);
